import { useEffect, useCallback } from "react";
import { useAdvisoryStore } from "../store/advisoryStore";
import { useOffline } from "./useOffline";
import { useLanguage } from "./useLanguage";
import { appConfig } from "../services/config/appConfig";

export function useAdvisory() {
  const { isOffline } = useOffline();
  const { language } = useLanguage();
  const store = useAdvisoryStore();

  // Load chat history from IndexedDB on mount
  useEffect(() => {
    store.loadHistory();
  }, []);

  const ask = useCallback(
    async (question, context = {}) => {
      if (!question?.trim()) return;
      await store.ask({
        question: question.trim(),
        language: language?.startsWith("ta") ? "ta" : "en",
        context: {
          district: appConfig.defaultLat ? "Coimbatore" : undefined,
          ...context,
        },
      });
    },
    [language, store],
  );

  return {
    messages: store.messages,
    loading: store.loading,
    error: store.error,
    offline: store.offline || isOffline,
    ragStatus: store.ragStatus,
    ask,
    clearError: store.clearError,
  };
}

export function useDiagnose() {
  const { language } = useLanguage();
  const store = useAdvisoryStore();

  useEffect(() => {
    store.loadDiagnoses();
  }, []);

  const diagnose = useCallback(
    async ({ symptoms, cropType }) => {
      return store.diagnose({
        symptoms,
        cropType,
        language: language?.startsWith("ta") ? "ta" : "en",
      });
    },
    [language, store],
  );

  return {
    diagnoses: store.diagnoses,
    loading: store.loading,
    error: store.error,
    diagnose,
    clearError: store.clearError,
  };
}

import React, { useState, useEffect, useCallback, useRef } from "react";
import { MapContainer, TileLayer, Marker, Popup, useMap } from "react-leaflet";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import { useTranslation } from "react-i18next";
import { useOffline } from "../hooks/useOffline";
import { useShops } from "../hooks/useShops";
import { useGeolocation } from "../hooks/useGeolocation";
import { distanceKm } from "../services/api/shopsService";
import {
  IconWifiOff,
  IconMapPin,
  IconPhone,
  IconRoute,
  IconX,
  IconCurrentLocation,
} from "@tabler/icons-react";

// ─── Fix Leaflet's broken default icon paths in bundled environments ──────────
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
  iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
});

// ─── Custom icons ─────────────────────────────────────────────────────────────
const makeIcon = (emoji, bg = "#16a34a") =>
  L.divIcon({
    className: "",
    html: `<div style="
      background:${bg};
      width:36px;height:36px;border-radius:50% 50% 50% 0;
      transform:rotate(-45deg);
      display:flex;align-items:center;justify-content:center;
      box-shadow:0 2px 8px rgba(0,0,0,0.25);border:2px solid #fff;
    ">
      <span style="transform:rotate(45deg);font-size:16px;line-height:1;">${emoji}</span>
    </div>`,
    iconSize: [36, 36],
    iconAnchor: [18, 36],
    popupAnchor: [0, -36],
  });

const USER_ICON = L.divIcon({
  className: "",
  html: `<div style="
    background:#2563eb;width:16px;height:16px;border-radius:50%;
    border:3px solid #fff;box-shadow:0 0 0 4px rgba(37,99,235,0.3);
  "></div>`,
  iconSize: [16, 16],
  iconAnchor: [8, 8],
});

const TYPE_CONFIG = {
  mandi: { emoji: "🏪", bg: "#b45309", tabKey: "maps.tab.mandi" },
  fertilizer: { emoji: "🌱", bg: "#16a34a", tabKey: "maps.tab.fertilizer" },
  seeds: { emoji: "🌾", bg: "#15803d", tabKey: "maps.tab.seeds" },
  education: { emoji: "🏛️", bg: "#7c3aed", tabKey: "maps.tab.education" },
  soillab: { emoji: "🏥", bg: "#0891b2", tabKey: "maps.tab.soillab" },
  office: { emoji: "🏢", bg: "#0369a1", tabKey: "maps.tab.office" },
  bank: { emoji: "🏦", bg: "#b91c1c", tabKey: "maps.tab.bank" },
  equipment: { emoji: "🔧", bg: "#92400e", tabKey: "maps.tab.equipment" },
  other: { emoji: "📍", bg: "#6b7280", tabKey: "maps.tab.all" },
};

const TABS = [
  { id: "all", key: "maps.tab.all", emoji: "🗺️" },
  { id: "mandi", key: "maps.tab.mandi", emoji: "🏪" },
  { id: "fertilizer", key: "maps.tab.fertilizer", emoji: "🌱" },
  { id: "education", key: "maps.tab.education", emoji: "🏛️" },
  { id: "soillab", key: "maps.tab.soillab", emoji: "🏥" },
];

// ─── Default center (Chennai, TN) — only used while GPS is loading ───────────
const DEFAULT_CENTER = [13.0827, 80.2707];
const DEFAULT_ZOOM = 11;

// ─── Helper: fly map to coords ────────────────────────────────────────────────
function FlyTo({ lat, lon, zoom }) {
  const map = useMap();
  useEffect(() => {
    if (lat != null && lon != null) map.flyTo([lat, lon], zoom ?? DEFAULT_ZOOM);
  }, [lat, lon, zoom, map]);
  return null;
}

// ─── Bottom sheet for selected marker ────────────────────────────────────────
function BottomSheet({ shop, onClose, userLat, userLon, t }) {
  if (!shop) return null;
  const cfg = TYPE_CONFIG[shop.type] ?? TYPE_CONFIG.other;
  const dist =
    userLat != null && shop.lat != null
      ? distanceKm(userLat, userLon, shop.lat, shop.lon).toFixed(1)
      : null;
  const mapsUrl = `https://www.google.com/maps/dir/?api=1&destination=${shop.lat},${shop.lon}`;

  return (
    <div className="fixed bottom-20 left-0 right-0 z-[9999] px-4 pointer-events-none">
      <div className="bg-white rounded-3xl shadow-2xl border border-gray-100 pointer-events-auto overflow-hidden max-w-lg mx-auto">
        {/* Drag handle */}
        <div className="flex justify-center pt-2 pb-1">
          <div className="w-10 h-1 rounded-full bg-gray-200" />
        </div>

        <div className="px-5 pb-5 pt-2">
          {/* Name + type badge */}
          <div className="flex items-start justify-between gap-2 mb-3">
            <div className="flex items-start gap-3 flex-1 min-w-0">
              <span className="text-2xl flex-shrink-0 mt-0.5">{cfg.emoji}</span>
              <div className="min-w-0">
                <h3 className="font-bold text-gray-900 text-base leading-tight">
                  {shop.name}
                </h3>
                {shop.address && (
                  <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">
                    {shop.address}
                  </p>
                )}
                {dist && (
                  <span className="inline-flex items-center gap-1 mt-1 text-xs text-gray-400">
                    <IconMapPin size={11} />
                    {dist} km {t("maps.distance")}
                  </span>
                )}
              </div>
            </div>
            <button
              className="flex-shrink-0 p-1.5 rounded-full hover:bg-gray-100 text-gray-400"
              onClick={onClose}
              aria-label="Close"
            >
              <IconX size={18} />
            </button>
          </div>

          {/* Action buttons */}
          <div className="flex gap-2">
            <a
              href={mapsUrl}
              target="_blank"
              rel="noreferrer"
              className="flex-1 flex items-center justify-center gap-1.5 bg-green-600 text-white rounded-xl py-2.5 text-sm font-semibold active:bg-green-700"
            >
              <IconRoute size={16} />
              {t("maps.directions")}
            </a>
            {shop.phone && (
              <a
                href={`tel:${shop.phone}`}
                className="flex-1 flex items-center justify-center gap-1.5 bg-blue-600 text-white rounded-xl py-2.5 text-sm font-semibold active:bg-blue-700"
              >
                <IconPhone size={16} />
                {t("maps.call")}
              </a>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────
export default function MapsPage() {
  const { t } = useTranslation();
  const { isOffline } = useOffline();
  const geo = useGeolocation();

  const userLat = geo.status === "success" ? geo.lat : null;
  const userLon = geo.status === "success" ? geo.lon : null;
  const mapCenter = userLat != null ? [userLat, userLon] : DEFAULT_CENTER;

  const { shops, status, source } = useShops({ lat: userLat, lon: userLon });

  // Also load static fallback for pure offline / no-data states
  const [staticShops, setStaticShops] = useState([]);
  useEffect(() => {
    fetch("/data/staticShops.json")
      .then((r) => r.json())
      .then((json) => setStaticShops(json.places ?? []))
      .catch(() => {});
  }, []);

  const [activeTab, setActiveTab] = useState("all");
  const [selectedShop, setSelectedShop] = useState(null);
  const [mapKey, setMapKey] = useState(0); // force remount on location change

  // Effective shops list: IDB/live data first, static fallback if empty
  const effectiveShops = shops.length > 0 ? shops : staticShops;

  // Filter by tab
  const visibleShops =
    activeTab === "all"
      ? effectiveShops
      : effectiveShops.filter((s) => s.type === activeTab);

  // When geolocation resolves, refresh map center
  useEffect(() => {
    if (geo.status === "success") setMapKey((k) => k + 1);
  }, [geo.status]);

  const handleMarkerClick = useCallback((shop) => setSelectedShop(shop), []);

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] -mx-4 relative">
      {/* ── Offline banner ───────────────────────────────────────────────── */}
      {isOffline && (
        <div className="mx-4 mb-2 flex items-center gap-2 bg-amber-50 border border-amber-200 rounded-2xl px-4 py-2 text-sm text-amber-700 flex-shrink-0">
          <IconWifiOff size={15} className="flex-shrink-0" />
          <span>{t("maps.offline")}</span>
        </div>
      )}

      {/* ── GPS status bar ───────────────────────────────────────────────── */}
      <div className="px-4 mb-2 flex-shrink-0">
        {geo.status === "loading" && (
          <div className="flex items-center gap-2 text-xs text-gray-500">
            <span className="loading loading-spinner loading-xs text-green-600" />
            {t("maps.loadingGPS")}
          </div>
        )}
        {(geo.status === "denied" || geo.status === "error") && (
          <div className="flex items-center justify-between gap-2">
            <span className="text-xs text-orange-600">
              {t("maps.gpsBlocked")}
            </span>
            <button
              onClick={geo.request}
              className="text-xs text-green-700 font-semibold underline"
            >
              {t("maps.getLocation")}
            </button>
          </div>
        )}
        {geo.status === "idle" && !userLat && (
          <p className="text-xs text-gray-400">{t("maps.noLocation")}</p>
        )}
        {geo.status === "success" && userLat && (
          <div className="flex items-center gap-1.5 text-xs text-green-700">
            <IconCurrentLocation size={12} />
            <span>
              {userLat.toFixed(4)}, {userLon.toFixed(4)}
            </span>
          </div>
        )}
      </div>

      {/* ── Category tabs ────────────────────────────────────────────────── */}
      <div className="flex gap-2 overflow-x-auto px-4 pb-2 flex-shrink-0 scrollbar-hide">
        {TABS.map((tab) => (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id);
              setSelectedShop(null);
            }}
            className={`flex-shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold transition-all ${
              activeTab === tab.id
                ? "bg-green-600 text-white shadow-sm"
                : "bg-gray-100 text-gray-600 hover:bg-gray-200"
            }`}
          >
            <span>{tab.emoji}</span>
            <span>{t(tab.key)}</span>
          </button>
        ))}
      </div>

      {/* ── Map area ─────────────────────────────────────────────────────── */}
      <div className="flex-1 relative">
        <MapContainer
          key={mapKey}
          center={mapCenter}
          zoom={DEFAULT_ZOOM}
          className="w-full h-full"
          zoomControl={false}
          attributionControl={false}
        >
          {/* OSM tile layer — cached by service worker for offline */}
          <TileLayer
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
          />

          {/* Fly-to when GPS resolves */}
          {userLat != null && <FlyTo lat={userLat} lon={userLon} zoom={13} />}

          {/* User location marker */}
          {userLat != null && (
            <Marker position={[userLat, userLon]} icon={USER_ICON}>
              <Popup>📍 Your location</Popup>
            </Marker>
          )}

          {/* Shop markers */}
          {visibleShops.map((shop) => {
            if (shop.lat == null || shop.lon == null) return null;
            const cfg = TYPE_CONFIG[shop.type] ?? TYPE_CONFIG.other;
            const icon = makeIcon(cfg.emoji, cfg.bg);
            return (
              <Marker
                key={shop.id}
                position={[shop.lat, shop.lon]}
                icon={icon}
                eventHandlers={{ click: () => handleMarkerClick(shop) }}
              >
                <Popup>
                  <strong>{shop.name}</strong>
                  {shop.address && (
                    <>
                      <br />
                      <span className="text-xs text-gray-500">
                        {shop.address}
                      </span>
                    </>
                  )}
                </Popup>
              </Marker>
            );
          })}
        </MapContainer>

        {/* Loading overlay */}
        {status === "loading" && (
          <div className="absolute inset-0 bg-white/60 flex items-center justify-center z-[1000]">
            <span className="loading loading-spinner loading-md text-green-600" />
          </div>
        )}

        {/* No results message */}
        {visibleShops.length === 0 && status !== "loading" && (
          <div className="absolute inset-0 flex items-center justify-center z-[1000] pointer-events-none">
            <div className="bg-white/90 rounded-2xl px-6 py-4 shadow text-center">
              <p className="text-sm text-gray-500">{t("maps.noResults")}</p>
            </div>
          </div>
        )}

        {/* Source badge */}
        <div className="absolute top-2 right-2 z-[1000]">
          {source === "cache" ||
          (shops.length === 0 && staticShops.length > 0) ? (
            <span className="bg-amber-100 text-amber-700 text-xs font-semibold px-2 py-1 rounded-full shadow-sm">
              📦 {isOffline ? "Cached" : "Saved"}
            </span>
          ) : source === "network" ? (
            <span className="bg-green-100 text-green-700 text-xs font-semibold px-2 py-1 rounded-full shadow-sm">
              🟢 Live
            </span>
          ) : null}
        </div>

        {/* Attribution (bottom-left) */}
        <div className="absolute bottom-1 left-1 z-[1000]">
          <span className="text-[9px] text-gray-400 bg-white/70 px-1 rounded">
            © OpenStreetMap
          </span>
        </div>
      </div>

      {/* ── Bottom sheet for selected marker ─────────────────────────────── */}
      {selectedShop && (
        <BottomSheet
          shop={selectedShop}
          onClose={() => setSelectedShop(null)}
          userLat={userLat}
          userLon={userLon}
          t={t}
        />
      )}
    </div>
  );
}

import { v4 as uuidv4 } from "uuid";
import { apiClient } from "./apiClient";
import { dbPut, dbGetAll, dbGet } from "../db/indexedDb";
import { DB_STORES } from "../db/schemas";
import { useAdvisoryStore } from "../store/advisoryStore";
import { queryOfflineBot, initOfflineChatbot } from "../offline/offlineChatbot";

// Initialize the offline AI worker globally early so it can download
// the models via Web Worker while user navigates naturally
initOfflineChatbot((status) => {
  console.log("Offline RAG Status:", status);
  useAdvisoryStore.getState().setRagStatus?.(status);
});

// ─── Chat history (persisted to IndexedDB) ────────────────────────────────────

export async function getChatHistory() {
  const rows = await dbGetAll(DB_STORES.chatHistory);
  return (rows ?? []).sort((a, b) => a.timestamp - b.timestamp);
}

async function saveMessage(role, text, meta = {}) {
  const record = { id: uuidv4(), role, text, timestamp: Date.now(), ...meta };
  await dbPut(DB_STORES.chatHistory, record);
  return record;
}

// ─── Ask AI ───────────────────────────────────────────────────────────────────

/**
 * Send a question to the KrishiVerse AI advisory backend.
 * Saves both the user question and AI answer to IndexedDB.
 *
 * @param {{ question, language?, context? }} payload
 * @returns {{ userMsg, aiMsg, answer }}
 */
export async function askAdvisory({ question, language = "en", context = {} }) {
  // Save user message immediately (optimistic)
  const userMsg = await saveMessage("user", question, { language });

  try {
    const { data } = await apiClient.post("/advisory/ask", {
      question,
      language,
      context,
    });
    const aiMsg = await saveMessage("assistant", data.answer, {
      model: data.model,
    });
    return { userMsg, aiMsg, answer: data.answer };
  } catch (err) {
    // If offline, use local bot logic
    if (err.isOffline) {
      const offlineAnswer = await queryOfflineBot(question);
      const offlineMsg = await saveMessage("assistant", offlineAnswer, {
        offline: true,
        model: "local-bot",
      });
      return {
        userMsg,
        aiMsg: offlineMsg,
        answer: offlineAnswer,
        offline: true,
      };
    }
    throw err;
  }
}

// ─── Diagnose ─────────────────────────────────────────────────────────────────

/**
 * Submit plant disease symptoms for AI diagnosis.
 * Saves result to diseaseDiagnoses store.
 *
 * @param {{ symptoms, cropType?, language? }} payload
 * @returns {{ id, diagnosis, savedAt }}
 */
export async function diagnoseCrop({ symptoms, cropType, language = "en" }) {
  const { data } = await apiClient.post("/advisory/diagnose", {
    symptoms,
    cropType,
    language,
  });

  const record = {
    id: uuidv4(),
    symptoms,
    cropType: cropType || "unknown",
    diagnosis: data.diagnosis,
    model: data.model,
    savedAt: Date.now(),
  };

  await dbPut(DB_STORES.diseaseDiagnoses, record);
  return record;
}

/**
 * Get all saved diagnoses.
 */
export async function getCachedDiagnoses() {
  const rows = await dbGetAll(DB_STORES.diseaseDiagnoses);
  return (rows ?? []).sort((a, b) => b.savedAt - a.savedAt);
}

import { apiClient } from "./apiClient";
import { dbGet, dbPut, dbGetAll } from "../db/indexedDb";
import { DB_STORES } from "../db/schemas";

const CROPS_CACHE_KEY = "all_crops";
const CROPS_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours

// ─── Crop list ────────────────────────────────────────────────────────────────

/**
 * Fetch all crops from backend and cache in IndexedDB.
 * Returns cached version if still fresh.
 */
export async function getCrops() {
  // Try cache first
  const cached = await dbGet(DB_STORES.meta, CROPS_CACHE_KEY);
  if (cached && Date.now() - cached.fetchedAt < CROPS_TTL_MS) {
    return cached.data;
  }

  try {
    const { data } = await apiClient.get("/crops");
    const record = {
      key: CROPS_CACHE_KEY,
      fetchedAt: Date.now(),
      data: data.crops,
    };
    await dbPut(DB_STORES.meta, record);
    return data.crops;
  } catch (err) {
    // Offline — return cached even if stale
    if (err.isOffline && cached) return cached.data;
    throw err;
  }
}

/**
 * Get a single crop by name.
 */
export async function getCrop(name) {
  try {
    const { data } = await apiClient.get(`/crops/${name}`);
    return data.crop;
  } catch (err) {
    // Offline fallback — search local cache
    if (err.isOffline) {
      const cached = await dbGet(DB_STORES.meta, CROPS_CACHE_KEY);
      return cached?.data?.find((c) => c.name === name) || null;
    }
    throw err;
  }
}

// ─── Crop recommendation ──────────────────────────────────────────────────────

/**
 * Get crop recommendations from backend rule-based engine.
 * This complements the TF.js ML model running on the frontend.
 *
 * @param {{ N, P, K, temperature, humidity, ph, rainfall, soilType? }} params
 * @returns {{ recommendations: Array, input: object }}
 */
export async function getRecommendations(params) {
  const { data } = await apiClient.post("/crops/recommend", params);
  return data;
}

import { dbGet, dbPut, dbGetAll } from "../db/indexedDb";
import { DB_STORES } from "../db/schemas";

// ─── Category map ─────────────────────────────────────────────────────────────

const CATEGORY_MAP = {
  agrarian: "fertilizer",
  garden_centre: "seeds",
  veterinary: "vet",
  government: "office",
  bank: "bank",
  college: "education",
  hardware: "equipment",
};

function classifyNode(el) {
  const t = el.tags ?? {};
  if (t.shop === "agrarian") return "fertilizer";
  if (t.shop === "garden_centre") return "seeds";
  if (t.amenity === "veterinary") return "vet";
  if (t.amenity === "bank") return "bank";
  if (t.office === "government" || t.office === "agricultural") return "office";
  if (t.amenity === "college" || t.amenity === "university") return "education";
  if (t.shop === "hardware") return "equipment";
  return "other";
}

function osmToPlace(el) {
  const t = el.tags ?? {};
  const name = t.name || t["name:en"] || t["name:ta"] || "Unknown Place";
  const street = [t["addr:housenumber"], t["addr:street"]]
    .filter(Boolean)
    .join(" ");
  const locality =
    t["addr:city"] ||
    t["addr:town"] ||
    t["addr:village"] ||
    t["addr:suburb"] ||
    "";
  const address =
    [street, locality].filter(Boolean).join(", ") || locality || "";

  return {
    id: `osm-${el.type}-${el.id}`,
    name,
    type: classifyNode(el),
    lat: el.lat ?? el.center?.lat,
    lon: el.lon ?? el.center?.lon,
    address,
    phone: t.phone || t["contact:phone"] || null,
    website: t.website || t["contact:website"] || null,
    tags: t,
  };
}

// ─── Overpass query ───────────────────────────────────────────────────────────

function buildQuery(lat, lon, radiusM) {
  const r = radiusM;
  const around = `(around:${r},${lat},${lon})`;
  return `
[out:json][timeout:30];
(
  node["shop"="agrarian"]${around};
  node["shop"="garden_centre"]${around};
  node["shop"="hardware"]${around};
  node["amenity"="veterinary"]${around};
  node["amenity"="bank"]["name"~"cooperative|gramin|kisan|nabard",i]${around};
  node["office"="government"]${around};
  node["office"="agricultural"]${around};
  node["amenity"="college"]["name"~"agriculture|krishi|farm|kvk",i]${around};
  way["shop"="agrarian"]${around};
  way["office"="government"]${around};
  way["office"="agricultural"]${around};
);
out center body qt;
`.trim();
}

// ─── Public API ───────────────────────────────────────────────────────────────

const CACHE_TTL = 2 * 60 * 60 * 1000; // 2 hours
const CACHE_KEY = (lat, lon) =>
  `overpass:${Number(lat).toFixed(3)},${Number(lon).toFixed(3)}`;

export async function getCachedShops(lat, lon) {
  if (lat == null) {
    // legacy: return all cached rows (original behaviour)
    return dbGetAll(DB_STORES.shops);
  }
  const record = await dbGet(DB_STORES.meta, CACHE_KEY(lat, lon));
  if (!record) return null;
  if (Date.now() - record.fetchedAt > CACHE_TTL) return null;
  return record.places;
}

export async function fetchNearbyPlaces({ lat, lon, radiusKm = 10 }) {
  const radiusM = radiusKm * 1000;
  const query = buildQuery(lat, lon, radiusM);

  const endpoints = [
    "https://overpass-api.de/api/interpreter",
    "https://overpass.kumi.systems/api/interpreter",
  ];

  let json = null;
  for (const url of endpoints) {
    try {
      const res = await fetch(url, {
        method: "POST",
        body: `data=${encodeURIComponent(query)}`,
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        signal: AbortSignal.timeout(20000),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      json = await res.json();
      break;
    } catch {
      // try next endpoint
    }
  }

  if (!json) throw new Error("Overpass API unreachable");

  const places = (json.elements ?? [])
    .map(osmToPlace)
    .filter((p) => p.lat != null && p.lon != null);

  // Cache in meta store
  await dbPut(DB_STORES.meta, {
    key: CACHE_KEY(lat, lon),
    fetchedAt: Date.now(),
    places,
  });

  // Also write to shops store for legacy reads
  await Promise.all(places.map((p) => dbPut(DB_STORES.shops, p)));

  return places;
}

/** Smart fetch — cache first, refresh if stale */
export async function getNearbyPlaces({ lat, lon, radiusKm = 10 }) {
  const cached = await getCachedShops(lat, lon);
  if (cached) return { places: cached, fromCache: true };
  const places = await fetchNearbyPlaces({ lat, lon, radiusKm });
  return { places, fromCache: false };
}

// ─── Haversine distance ───────────────────────────────────────────────────────

export function distanceKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

