import { create } from "zustand";
import {
  askAdvisory,
  getChatHistory,
  diagnoseCrop,
  getCachedDiagnoses,
} from "../services/api/advisoryService";

export const useAdvisoryStore = create((set, get) => ({
  messages: [],
  diagnoses: [],
  loading: false,
  error: null,
  offline: false,
  ragStatus: "uninitialized",
  setRagStatus: (status) => set({ ragStatus: status }),

  // Load persisted chat history from IndexedDB
  loadHistory: async () => {
    try {
      const messages = await getChatHistory();
      set({ messages });
    } catch (err) {
      set({ error: err.message });
    }
  },

  // Load past diagnoses
  loadDiagnoses: async () => {
    try {
      const diagnoses = await getCachedDiagnoses();
      set({ diagnoses });
    } catch (err) {
      set({ error: err.message });
    }
  },

  // Send a question to the AI
  ask: async ({ question, language, context }) => {
    set({ loading: true, error: null, offline: false });
    try {
      const { userMsg, aiMsg, offline } = await askAdvisory({
        question,
        language,
        context,
      });
      set((state) => ({
        messages: [...state.messages, userMsg, aiMsg],
        loading: false,
        offline: !!offline,
      }));
    } catch (err) {
      set({ error: err.message, loading: false });
      throw err;
    }
  },

  // Diagnose a crop disease
  diagnose: async ({ symptoms, cropType, language }) => {
    set({ loading: true, error: null });
    try {
      const result = await diagnoseCrop({ symptoms, cropType, language });
      set((state) => ({
        diagnoses: [result, ...state.diagnoses],
        loading: false,
      }));
      return result;
    } catch (err) {
      set({ error: err.message, loading: false });
      throw err;
    }
  },

  clearError: () => set({ error: null }),
}));
